	// Install or heal the durable integration selected by the repository's hook
	// manager, so the hook hot path repairs a manager refresh immediately.
	//
	// Gated on an inspection first, because "idempotent" describes the outcome
	// and not the cost: a bare EnsureGitHookIntegration runs manager detection,
	// a native repair probe, a 17-file snapshot, the installer, and then a full
	// re-inspection to verify — measured at 63ms native and 139ms with Lefthook,
	// on EVERY turn start, in a repo where nothing is wrong. The gate this
	// replaces (`if !IsGitHookInstalled(ctx)`) cost 0.15ms.
	//
	// Deliberately gated HERE rather than inside the coordinator. The health
	// check is blind to absolute_git_hook_path by design —
	// validNativeHookCommandPrefix accepts the bare `entire` form and an
	// absolute path equally — so an early-out inside the coordinator would stop
	// honoring a flipped flag, which is the regression b785b265e fixed. This
	// caller passes the ambient setting and never changes it; the callers that
	// do act on an explicit flag (`entire enable`, `configure`, `doctor`) call
	// the coordinator directly and still run it in full.
	if health := CheckGitHookIntegration(ctx); health.State == GitHookIntegrationCurrent {
		return nil
	}
	if _, err := EnsureGitHookIntegration(ctx, hookSettingsFromConfig(ctx)); err != nil {
		return fmt.Errorf("failed to install git hooks: %w", err)
	}
	return nil
}

