			AgentType:    types.AgentType("Claude Code"),
		},
	}
	for _, st := range states {
		require.NoError(t, store.Save(ctx, st))
	}

	type snap struct {
		data []byte
		mod  time.Time
	}
	before := map[string]snap{}
	for _, st := range states {
		path := sessionStatePathForTest(t, st.SessionID)
		data, readErr := os.ReadFile(path)
		require.NoError(t, readErr)
		info, statErr := os.Stat(path)
		require.NoError(t, statErr)
		before[st.SessionID] = snap{data: data, mod: info.ModTime()}
	}

	var buf bytes.Buffer
	writeActiveSessions(ctx, &buf, newStatusStyles(&buf))
	output := buf.String()

	for _, st := range states {
		assert.Contains(t, output, st.SessionID[:8],
			"every session must be listed, not collapsed by agent")
	}

	for id, want := range before {
		path := sessionStatePathForTest(t, id)
		got, readErr := os.ReadFile(path)
		require.NoError(t, readErr, "status must not delete session state")
		assert.Equal(t, want.data, got, "status must not rewrite session state")
		info, statErr := os.Stat(path)
		require.NoError(t, statErr)
		assert.True(t, want.mod.Equal(info.ModTime()),
			"status must not touch session state mtime")
	}
}

