		// own hook reaches it directly. Anything else — absent, a symlink, or
		// another tool's script — does not.
		if isLefthookLauncher(root, hook, hook) || fileContains(root, hook, entireHookMarker) {
			continue
		}
		uncovered = append(uncovered, hook)
	}
	return uncovered
}

